// n8n Code Node
const input = $input.first().json.body.location; // e.g., "next to player Mauri67"

function parseLocation(input) {
    const coordMatch = input.match(/^(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)\s*[,\s]\s*(-?\d+\.?\d*)$/);
    if (coordMatch) {
        return {
            type: 'coordinates',
            x: parseFloat(coordMatch[1]),
            y: parseFloat(coordMatch[2]),
            z: parseFloat(coordMatch[3])
        };
    }

    const playerMatch = input.match(/(?:next\s+to\s+)?player\s+(\w+)/i);
    if (playerMatch) {
        return {
            type: 'player',
            name: playerMatch[1]
        };
    }

    return {
        type: 'landmark',
        name: input.trim()
    };
}

const location = parseLocation(input);
return { location };

const status = $json;
return {
  Position: {
    x: Math.floor(status.position?.x || 0),
    y: Math.floor(status.position?.y || 64),
    z: Math.floor(status.position?.z || 0)
  }
}

const buildLocation = $('Teleport Workers').first().json.buildLocation;
const tasks = $input.first().json;

const houseX = buildLocation.x;
const houseY = buildLocation.y;
const houseZ = buildLocation.z;

const zMin = houseZ - 3;
const zMax = houseZ + 3;

// Get all worker names sorted numerically (Worker1, Worker2, Worker3, etc.)
const workerNames = Object.keys(tasks).sort((a, b) => {
  const numA = parseInt(a.match(/\d+/)[0]);
  const numB = parseInt(b.match(/\d+/)[0]);
  return numA - numB;
});

const numWorkers = workerNames.length;
const totalWidth = 7; // 7x7 footprint = 7 blocks wide
const blocksPerWorker = totalWidth / numWorkers;

const updatedTasks = {};

workerNames.forEach((workerName, index) => {
  // Calculate absolute coordinates for this worker
  const workerXMin = Math.floor(houseX - 3 + index * blocksPerWorker);
  const workerXMax = Math.floor(houseX - 3 + (index + 1) * blocksPerWorker);

  // Determine boundaries with adjacent workers
  const prevWorker = index > 0 ? workerNames[index - 1] : null;
  const nextWorker = index < numWorkers - 1 ? workerNames[index + 1] : null;

  let task = tasks[workerName];

  // Replace scope section (works for any pattern)
  task = task.replace(
    /Scope:[\s\S]*?(?=\n\nSubtasks)/,
    `Scope: ABSOLUTE COORDINATES - x:${workerXMin} to ${workerXMax}, z:${zMin} to ${zMax}, y:${houseY} to ${houseY + 4}.`
  );

  // Replace "Within your region" references
  task = task.replace(
    /Within your(?:\s+ABSOLUTE)?\s+region[^.]*\./g,
    `Within your ABSOLUTE region (x:${workerXMin} to ${workerXMax}, z:${zMin} to ${zMax}).`
  );

  // Replace "Do NOT place or break blocks outside" constraints
  task = task.replace(
    /Do NOT place or break blocks outside your defined[^.]*region[^.]*\./g,
    `Do NOT place or break blocks outside your defined ABSOLUTE region (x:${workerXMin} to ${workerXMax}, z:${zMin} to ${zMax}).`
  );

  // Replace boundary/axis references (flexible for any coordinate)
  task = task.replace(
    /(?:central\s+)?(?:boundary|axis)(?:\s+at\s+x:[0-9\-]+)?/g,
    (match) => {
      if (match.includes('boundary')) {
        return nextWorker ? `boundary at x:${workerXMax}` : `boundary at x:${workerXMin}`;
      }
      return `axis at x:${Math.floor((workerXMin + workerXMax) / 2)}`;
    }
  );

  // Build boundary information
  let boundaryInfo = '';
  if (prevWorker) boundaryInfo += `The boundary with ${prevWorker} is at x:${workerXMin}. `;
  if (nextWorker) boundaryInfo += `The boundary with ${nextWorker} is at x:${workerXMax}.`;

  // Replace or add CRITICAL section
  if (task.includes('CRITICAL:')) {
    task = task.replace(
      /CRITICAL:[\s\S]*?(?=\n\nWork together)/,
      `CRITICAL: Use ABSOLUTE coordinates x:${workerXMin} to ${workerXMax}, z:${zMin} to ${zMax}, y:${houseY} to ${houseY + 4}. ${boundaryInfo}`
    );
  } else {
    task = task.replace(
      'Work together with nearby workers',
      `CRITICAL: Use ABSOLUTE coordinates x:${workerXMin} to ${workerXMax}, z:${zMin} to ${zMax}, y:${houseY} to ${houseY + 4}. ${boundaryInfo}\n\nWork together with nearby workers`
    );
  }

  updatedTasks[workerName] = task;
});

return updatedTasks;

const taskDivision = $('Webhook').first().json.body.taskDivision;
const buildRequest = $('Webhook').first().json.body.buildRequest;

let coordinatedTasks = {};

Object.entries(taskDivision).forEach(([workerName, task]) => {
  // Fix undefined blockBreakLimit
  const blockLimit = task.blockBreakLimit || "Do not break more than ~300 blocks";

  const taskDescription = `
Objective: ${task.objective}

Scope: ${task.scope}

Subtasks:
${task.subtasks.map((t, i) => `${i + 1}. ${t}`).join('\n')}

Block Break Limit: ${blockLimit}

Assumptions: ${task.assumptions}

Constraints: ${task.constraints}`;

  coordinatedTasks[workerName] = `Help build: ${buildRequest}

Your specific contribution:${taskDescription}

Work together with nearby workers to create a cohesive structure. Position yourself strategically to connect your work with others.`;
});

return coordinatedTasks;
